# PatientContextExample

ID: design-system-emr-emrpatientcontextbar

프로젝트 Storybook 전용 초기 상태 CSF 예시입니다. import 코드와 선택한 snippet을 함께 사용하세요. 기존 preview의 합성 mock·CSS·Next.js shim 설정에서 실행해야 하며 운영 화면에 그대로 붙여 넣는 코드가 아닙니다. 실제 컴포넌트 API는 포함된 함수 본문을 참고하세요. args·render·decorators·fixture hook과 정리 함수는 원본을 보존하며, play 검증은 생략하므로 상호작용 이후 상태를 재현하지 않습니다.

## Stories

### Callbacks

Story ID: design-system-emr-emrpatientcontextbar--callbacks

```
// 프로젝트 Storybook 전용 초기 상태 CSF 예시입니다. import 코드와 선택한 snippet을 함께 사용하세요. 기존 preview의 합성 mock·CSS·Next.js shim 설정에서 실행해야 하며 운영 화면에 그대로 붙여 넣는 코드가 아닙니다. 실제 컴포넌트 API는 포함된 함수 본문을 참고하세요. args·render·decorators·fixture hook과 정리 함수는 원본을 보존하며, play 검증은 생략하므로 상호작용 이후 상태를 재현하지 않습니다.
import { useId, useState } from "react";
import type { Meta, StoryObj } from "@storybook/nextjs-vite";

import { EmrPatientContextBar } from "@/components/emr/patient-context-bar";

type ContextArgs = { unavailable: boolean; narrow: boolean; minimal: boolean };
function PatientContextExample({ unavailable, narrow, minimal }: ContextArgs) {
  const historyId = useId();
  const [historyOpen, setHistoryOpen] = useState(false);
  const [panelOpen, setPanelOpen] = useState(false);
  const [lastAction, setLastAction] = useState("없음");
  return <div className="grid gap-3" style={{ width: narrow ? 420 : "100%", maxWidth: 1280 }}>
    <EmrPatientContextBar
      patientItems={[{ label: "환자명", value: narrow ? "합성 긴 환자 이름으로 가로 스크롤 확인" : "합성 환자" }, { label: "종류", value: "개" }]}
      guardianItems={minimal ? [] : [{ label: "보호자", value: "합성 보호자" }]}
      patientInteraction={minimal ? undefined : { ariaLabel: "합성 환자 프로필 열기", preview: <p>합성 환자 미리보기</p>, onActivate: () => setLastAction("환자 프로필") }}
      guardianInteraction={minimal ? undefined : { ariaLabel: "합성 보호자 프로필 열기", preview: <p>합성 보호자 미리보기</p>, onActivate: () => setLastAction("보호자 프로필") }}
      historyButton={minimal ? undefined : { controls: historyId, expanded: historyOpen, onClick: () => setHistoryOpen((value) => !value) }}
      vitalItems={minimal ? [] : [{ label: "체중", value: "합성 5 kg", measurementTooltip: "합성 측정값 · 2026-05-01" }]}
      vitalAction={minimal ? undefined : { ariaLabel: "합성 바이탈 입력", disabled: unavailable, disabledReason: unavailable ? "합성 읽기 전용 상태입니다." : undefined, onActivate: () => setLastAction("바이탈") }}
      memoActions={minimal ? [] : [
        { label: "방문", summary: "합성 방문 메모", onClick: () => setLastAction("방문 메모") },
        { label: "보호자", locked: true, unavailableReason: "합성 잠김 메모입니다." },
        { label: "환자", disabled: true, unavailableReason: "합성 비활성 메모입니다." },
        { label: "수납", summary: "합성 조회 전용 메모" },
      ]}
      onToggleRightPanel={minimal ? undefined : () => setPanelOpen((value) => !value)}
      rightPanelOpen={panelOpen}
      rightPanelDisabled={unavailable}
      rightPanelToggleLabel="장비결과"
      rightPanelBadgeCount={minimal ? undefined : 2}
    />
    <output>실행: {lastAction}</output>
    <div id={historyId} data-testid="synthetic-context-history" hidden={!historyOpen}>합성 이력 본문</div>
    <div data-testid="synthetic-context-panel" hidden={!panelOpen}>합성 장비결과 본문</div>
  </div>;
}

const meta = {
  title: "Design System/EMR/EmrPatientContextBar",
  component: PatientContextExample,
  tags: ["autodocs"],
  parameters: { docs: { description: { component: "수납·차트·조제·검사·영상의 환자 맥락을 보여주는 공통 bar입니다. 호출자는 datum 배열, profile preview/activation, vital action, memo 상태, 이력·오른쪽 패널 상태를 제공합니다. profile click은 onActivate를 호출하며 hover preview와 별개입니다. unavailable/narrow/minimal은 이 Storybook fixture의 조건이며 runtime prop 이름이 아닙니다. 합성 표시·콜백만 사용하고 권한·저장·실제 환자 정보를 처리하지 않습니다." } } },
  args: { unavailable: false, narrow: false, minimal: false },
  argTypes: {
    unavailable: { control: "boolean", description: "fixture에서 vital과 오른쪽 패널 작업을 사용할 수 없는 상태입니다." },
    narrow: { control: "boolean", description: "420px와 긴 합성 이름으로 overflow를 보여줍니다." },
    minimal: { control: "boolean", description: "필수 patientItems만 제공하는 fixture입니다." },
  },
  render: (args) => <PatientContextExample key={`${args.unavailable}:${args.minimal}`} {...args} />,
} satisfies Meta<ContextArgs>;
type Story = StoryObj<typeof meta>;
async function waitForContext(check: () => boolean, message: string) {
  const deadline = performance.now() + 2000;
  while (!check()) {
    if (performance.now() >= deadline) throw new Error(message);
    await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
  }
}
 const Callbacks: Story = {
  parameters: { docs: { description: { story: "환자·보호자 프로필 활성화, 바이탈, 이력과 오른쪽 패널의 로컬 콜백을 검증합니다. hover preview, 실제 Tab/Enter 이동, 메모 팝오버 작업은 별도 브라우저 검증 대상입니다." } } },
};
 const UnavailableActions: Story = {
  args: { unavailable: true },
  parameters: { docs: { description: { story: "바이탈 작업은 aria-disabled와 설명을 유지하는 포커스 가능한 버튼입니다. 오른쪽 패널 버튼은 native disabled입니다. 잠김/비활성/조회 메모가 함께 제공됩니다." } } },
};
 const MemoStates: Story = {
  parameters: { docs: { description: { story: "방문 메모만 로컬 callback을 제공합니다. 잠김·비활성·callback 없는 조회 항목은 팝오버에서 선택할 수 없습니다. 활성 항목을 선택하면 결과가 바뀌고 팝오버가 닫힙니다." } } },
};
 const NarrowOverflow: Story = { args: { narrow: true }, parameters: { docs: { description: { story: "긴 합성 정보와 좁은 폭의 가로 overflow 예시입니다. 스크롤 끝 이동·gradient의 시각 결과는 브라우저 검증 전입니다." } } } };
 const PatientOnly: Story = { args: { minimal: true }, parameters: { docs: { description: { story: "선택적인 보호자·바이탈·메모·패널 작업 없이 patientItems만 보여줍니다." } } } };

export default meta;
export { Callbacks };
```

